<?php
require_once __DIR__.'/includes/functions.php';require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/csrf.php';$id=(int)($_GET['id']??0);$pdo=db();$s=$pdo->prepare("SELECT l.*,u.name seller_name,u.created_at seller_since,u.is_active seller_active,(SELECT COALESCE(AVG(rating),0) FROM reviews WHERE reviewed_user_id=u.id) seller_rating,(SELECT image_path FROM listing_images WHERE listing_id=l.id ORDER BY id LIMIT 1) image_path FROM listings l JOIN users u ON u.id=l.user_id WHERE l.id=? LIMIT 1");$s->execute([$id]);$l=$s->fetch();if(!$l){http_response_code(404);exit('Listing not found.');}$imgs=$pdo->prepare('SELECT * FROM listing_images WHERE listing_id=? ORDER BY id');$imgs->execute([$id]);$images=$imgs->fetchAll();$user=current_user();$isAdmin=$user&&($user['role']??'')==='admin';$isOwner=$user&&((int)$user['id']===(int)$l['user_id']);$participant=false;if($user&&!$isOwner&&!$isAdmin){$t=$pdo->prepare("SELECT 1 FROM trade_requests WHERE listing_id=? AND (buyer_id=? OR seller_id=?) AND status IN ('accepted','completed') LIMIT 1");$t->execute([$id,$user['id'],$user['id']]);$participant=(bool)$t->fetchColumn();}$availability=(string)($l['availability_status']??'available');$publicVisible=$l['status']==='approved'&&(int)$l['seller_active']===1&&in_array($availability,['available','reserved'],true);if(!$publicVisible&&!$isOwner&&!$isAdmin&&!$participant){http_response_code(404);exit('Listing not available.');}$pred=null;if($isAdmin){$p=$pdo->prepare('SELECT * FROM fraud_predictions WHERE listing_id=? ORDER BY id DESC LIMIT 1');$p->execute([$id]);$pred=$p->fetch();}$publicModerationStatus=$l['status']==='approved'?(string)$l['status']:null;$available=$publicVisible&&$availability==='available';$pageTitle=$l['title'];include __DIR__.'/includes/header.php';?>
<div class="detail"><div><img class="gallery-main" src="<?=e($images?$images[0]['image_path']:listing_visual($l))?>" alt="<?=e($l['title'])?>"><div class="card card-body" style="margin-top:18px"><h3>Description</h3><p style="line-height:1.7"><?=nl2br(e($l['description']))?></p></div></div><aside class="detail-panel"><div class="actions" style="margin-top:0"><span class="badge <?=e(trust_class((string)($l['trust_status']??''),$publicModerationStatus))?>"><?=e(trust_label((string)($l['trust_status']??''),$publicModerationStatus))?></span><span class="availability-pill"><?=e(availability_label($availability))?></span></div><?php if($l['status']!=='approved'):?><div class="muted" style="margin-top:8px">This listing is private while moderation is pending.</div><?php elseif(is_admin_reviewed((string)($l['trust_status']??''),(string)$l['status'])):?><div class="muted" style="margin-top:8px">A human administrator reviewed this listing before it was made public.</div><?php endif;?><h1><?=e($l['title'])?></h1><div class="price" style="font-size:32px"><?=money($l['price'])?></div><div class="stack" style="margin-top:18px"><div><strong>Condition</strong><br><span class="muted"><?=e($l['item_condition'])?></span></div><div><strong>Brand</strong><br><span class="muted"><?=e($l['brand']?:'Not specified')?></span></div><div><strong>Location</strong><br><span class="muted"><?=e($l['location'])?></span></div><div><strong>Seller</strong><br><a class="muted" href="/profile.php?id=<?=$l['user_id']?>"><?=e($l['seller_name'])?> · <?=number_format((float)$l['seller_rating'],1)?>/5</a></div></div><?php if($user&&!$isOwner&&$available):?><div class="actions"><form method="post" action="/api/chat.php"><?=csrf_field()?><input type="hidden" name="action" value="start"><input type="hidden" name="listing_id" value="<?=$id?>"><button class="btn">Chat with seller</button></form><form method="post" action="/api/trade.php"><?=csrf_field()?><input type="hidden" name="action" value="request"><input type="hidden" name="listing_id" value="<?=$id?>"><button class="btn btn-light">Send trade request</button></form><a class="btn btn-light" href="/report.php?listing_id=<?=$id?>">Report</a></div><?php elseif(!$user&&$available):?><div class="actions"><a class="btn" href="/login.php">Login to chat or trade</a></div><?php endif;?><?php if($isOwner&&$availability!=='sold'&&$l['status']!=='removed'):?><div class="actions"><?php if(in_array($availability,['available','withdrawn'],true)):?><a class="btn btn-light" href="/edit-listing.php?id=<?=$id?>">Edit listing</a><?php endif;?><form method="post" action="/delete-listing.php" data-confirm="Withdraw this listing?"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><button class="btn btn-danger">Withdraw</button></form></div><?php endif;?></aside></div><?php if($isAdmin&&$pred):?><div class="card card-body" style="margin-top:28px"><h2>RADIUS TRUST ANALYSIS</h2><div class="price"><?=e($pred['fraud_score'])?> / 100</div><?php foreach(['image_score'=>'Image Similarity','price_score'=>'Price Anomaly','seller_score'=>'Seller Risk','text_score'=>'Text Risk','policy_score'=>'Policy Risk']as$k=>$label):?><div class="risk-row"><span><?=$label?></span><div class="bar"><i style="width:<?=min(100,(float)$pred[$k])?>%"></i></div><strong><?=round((float)$pred[$k])?></strong></div><?php endforeach;?><h3>Explanation</h3><p><?=e($pred['explanation'])?></p><form method="post" action="/api/fraud.php" class="actions"><?=csrf_field()?><input type="hidden" name="listing_id" value="<?=$id?>"><?php if($l['status']!=='approved'&&$l['status']!=='removed'):?><button class="btn" name="action" value="approve">Approve</button><?php endif;?><?php if($l['status']!=='removed'):?><button class="btn btn-danger" name="action" value="remove">Remove</button><?php endif;?><button class="btn btn-light" name="action" value="retry">Retry Analysis</button></form></div><?php endif;?><?php include __DIR__.'/includes/footer.php';?>
